def transform(grid):
    """Complete a grid using its simplest observed modular stripe pattern."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Each color is constant on classes of a linear coordinate modulo p.
    # This handles diagonal bands (r-c or r+c), vertical cycles, and
    # horizontal cycles with one compact rule.
    coeffs = (-1, 0, 1)
    for p in range(1, max(h, w) + 1):
        for a in coeffs:
            for b in coeffs:
                if a == 0 and b == 0:
                    continue
                colors = {}
                valid = True
                for r in range(h):
                    for c in range(w):
                        color = grid[r][c]
                        if color == 0:
                            continue
                        key = (a * r + b * c) % p
                        if key in colors and colors[key] != color:
                            valid = False
                            break
                        colors[key] = color
                    if not valid:
                        break
                if not valid:
                    continue
                # Avoid choosing a rule that leaves any cell's class unknown.
                keys = {(a * r + b * c) % p for r in range(h) for c in range(w)}
                if keys <= colors.keys():
                    return [[colors[(a * r + b * c) % p]
                             for c in range(w)] for r in range(h)]

    # If the clues do not define a complete modular template, preserve known
    # cells rather than inventing colors.
    return [row[:] for row in grid]
